using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows;
using System.Windows.Threading;

namespace AkilliKisayol {
 public static class ResponsivenessTests {
  public static int Headless(){var results=new List<object>();string report=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"persistence-test-results.json");try{Unit((passed,name)=>{results.Add(new{passed=passed,name=name});if(!passed)throw new Exception(name);});File.WriteAllText(report,LocalLlm.Json().Serialize(new{status="PASS",completed=results.Count,results=results}));return 0;}catch(Exception error){File.WriteAllText(report,LocalLlm.Json().Serialize(new{status="FAIL",completed=results.Count,error=error.ToString(),results=results}));return 1;}}
  static State StateWith(string name){return new State{History=new List<Activity>{new Activity{Time="2026-01-01",Name=name,Result="Fixture"}}};}
  static void Clean(string folder){string full=Path.GetFullPath(folder),allowed=Path.Combine(Path.GetTempPath(),"MakroPlus-Responsiveness-");if(!full.StartsWith(allowed,StringComparison.OrdinalIgnoreCase))throw new InvalidOperationException("Unexpected test cleanup directory.");if(Directory.Exists(full)){foreach(string file in Directory.GetFiles(full,"*",SearchOption.AllDirectories))File.SetAttributes(file,FileAttributes.Normal);Directory.Delete(full,true);}}
  static void PumpUntil(Func<bool> done){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(10)};var deadline=DateTime.UtcNow.AddSeconds(10);timer.Tick+=(s,e)=>{if(done()||DateTime.UtcNow>deadline){timer.Stop();frame.Continue=false;}};timer.Start();Dispatcher.PushFrame(frame);if(!done())throw new TimeoutException("Responsiveness fixture did not complete.");}
  public static void Unit(Action<bool,string> check){
   string root=Path.Combine(Path.GetTempPath(),"MakroPlus-Responsiveness-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);
   try{
    string file=Path.Combine(root,"ordered.json");var state=StateWith("captured");var old=Storage.Capture(state);state.History[0].Name="mutated";Storage.Write(old,file);check(Storage.Read(file).History[0].Name=="captured","Storage snapshots detach mutable state before a background write");
    var latest=Storage.Capture(StateWith("configuration"));Storage.Write(latest,file);Storage.Write(old,Path.Combine(root,".","ordered.json"));Storage.Write(old,file.ToUpperInvariant());check(Storage.Read(file).History[0].Name=="configuration","A late history snapshot cannot overwrite a newer settings save, including normalized/case-varied paths");
    string backup=File.ReadAllText(file+".bak");Storage.Write(latest,file);check(File.ReadAllText(file+".bak")==backup,"Rewriting the same snapshot is a no-op and preserves the previous backup");
    string separate=Path.Combine(root,"other.json");Storage.Write(old,separate);check(Storage.Read(separate).History[0].Name=="captured","Snapshot ordering is per destination file, not a global dropped-write flag");
    string parallel=Path.Combine(root,"parallel.json");var snapshots=Enumerable.Range(0,48).Select(i=>Storage.Capture(StateWith("writer-"+i))).ToArray();Task.WaitAll(snapshots.Reverse().Select(s=>Task.Run(()=>Storage.Write(s,parallel))).ToArray());check(Storage.Read(parallel).History[0].Name=="writer-47","Parallel writers retain the newest captured snapshot");
    var retry=Storage.Capture(StateWith("retry"));bool failed=false;using(var held=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read)){try{Storage.Write(retry,file);}catch(IOException){failed=true;}}check(failed&&Storage.Read(file).History[0].Name=="configuration","A locked destination fails without replacing the last valid settings");Storage.Write(retry,file);check(Storage.Read(file).History[0].Name=="retry","A failed snapshot remains eligible for a later retry");
    File.SetAttributes(file,File.GetAttributes(file)|FileAttributes.ReadOnly);failed=false;try{Storage.Write(Storage.Capture(StateWith("read-only")),file);}catch(IOException){failed=true;}catch(UnauthorizedAccessException){failed=true;}finally{File.SetAttributes(file,FileAttributes.Normal);}check(failed&&Storage.Read(file).History[0].Name=="retry","Read-only destination failure preserves valid data");check(Directory.GetFiles(root,"*.tmp").Length==0,"Failed and skipped writes leave no temporary settings files");
    failed=false;try{Storage.Write((Storage.Snapshot)null,file);}catch(ArgumentNullException){failed=true;}check(failed,"Null snapshot writes fail explicitly");
    var expected=new HashSet<int>(new[]{33,34,35,36,37,38,39,40,45,46,91,92,111,144,165,163,173,174,175,176,177,179});bool flags=true;for(int key=0;key<256;key++){uint value=expected.Contains(key)?1u:0u;if(Native.KeyFlagsForTest(key,false)!=value||Native.KeyFlagsForTest(key,true)!=(value|2u))flags=false;}check(flags,"Static extended-key lookup preserves down/up flags for every virtual key");
    check(!PointerEngine.HandlesMessage(0x200)&&!PointerEngine.HandlesMessage(0x203)&&!PointerEngine.HandlesMessage(0x20D)&&!PointerEngine.HandlesMessage(0x210),"Pointer hook filters movement and unsupported messages before marshaling");check(new[]{0x201,0x202,0x204,0x205,0x207,0x208,0x20A,0x20B,0x20C,0x20E}.All(PointerEngine.HandlesMessage),"All supported mouse button and wheel messages reach the hook handler");
    Benchmark(root,check);
   }finally{Clean(root);}
  }
  static void Benchmark(string root,Action<bool,string> check){
   var state=StateWith("benchmark");state.Bindings=Enumerable.Range(0,40).Select(i=>new Binding{Name="Fixture "+i,Key=119,Kind="Send key",SendKey=67,SendMods=2}).ToList();state.History=Enumerable.Range(0,200).Select(i=>new Activity{Name="Fixture action "+i,Time="2026-01-01 00:00:00 +00:00",Result="Synthetic history result"}).ToList();var capture=new List<double>();var disk=new List<double>();int owner=Thread.CurrentThread.ManagedThreadId;bool offThread=true;
   for(int i=0;i<55;i++){var watch=Stopwatch.StartNew();var snapshot=Storage.Capture(state);watch.Stop();double captured=watch.Elapsed.TotalMilliseconds;var sample=Task.Run(()=>{var timer=Stopwatch.StartNew();Storage.Write(snapshot,Path.Combine(root,"benchmark.json"));return new{ms=timer.Elapsed.TotalMilliseconds,worker=Thread.CurrentThread.ManagedThreadId!=owner};}).GetAwaiter().GetResult();offThread&=sample.worker;if(i>=5){capture.Add(captured);disk.Add(sample.ms);}}
   capture.Sort();disk.Sort();check(offThread,"History disk benchmark writes execute on workers, not the snapshot owner thread");File.WriteAllText(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"history-persistence-performance.json"),LocalLlm.Json().Serialize(new{bindings=40,historyEntries=200,samples=50,captureMedianMilliseconds=(capture[24]+capture[25])/2,captureP95Milliseconds=capture[47],diskMedianMilliseconds=(disk[24]+disk[25])/2,diskP95Milliseconds=disk[47],diskMaximumMilliseconds=disk[49],diskRunsOffOwnerThread=offThread,scope="One development computer; real Flush(true) writes. Capture remains on the state owner. Microsecond hook savings are not claimed."}));
  }
  public static void Ui(MainWindow owner,Action<bool,string> check){
   HookPaths(check);
   string root=Path.Combine(Path.GetTempPath(),"MakroPlus-Responsiveness-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);var state=StateWith("initial");string file=Path.Combine(root,"ui.json");var window=new MainWindow(state,file){Owner=owner};window.Show();
   try{
    var capture=window.CaptureHistory;window.CaptureHistory=s=>{throw new IOException("Fixture serialization failure");};window.LogHistoryForTest("capture-failure");window.FlushHistoryForTest();check(window.HistoryDirtyForTest,"Serialization failure keeps unsaved history marked dirty");window.CaptureHistory=capture;
    var entered=new ManualResetEventSlim();var release=new ManualResetEventSlim();Task pending=null;window.WriteHistoryAsync=(snapshot,path)=>pending=Task.Run(()=>{entered.Set();if(!release.Wait(8000))throw new TimeoutException("Fixture writer release missing");Storage.Write(snapshot,path);});window.FlushHistoryForTest();PumpUntil(()=>entered.IsSet);bool pulse=false;Application.Current.Dispatcher.BeginInvoke(DispatcherPriority.Input,new Action(()=>pulse=true));PumpUntil(()=>pulse);check(pulse&&!pending.IsCompleted,"UI input queue continues while a history disk writer is held on a background task");
    state.StepIntervalMs=50;check(window.SaveSettingsForTest(),"Configuration edits still save synchronously while an older history snapshot is pending");release.Set();PumpUntil(()=>pending.IsCompleted);pending.GetAwaiter().GetResult();check(Storage.Read(file).StepIntervalMs==50&&Storage.Read(file).History.Any(h=>h.Name=="capture-failure"),"A released older history writer cannot roll back a saved configuration edit");entered.Dispose();release.Dispose();
    var failure=new TaskCompletionSource<bool>();window.WriteHistoryAsync=(snapshot,path)=>failure.Task;window.LogHistoryForTest("obsolete-error");window.FlushHistoryForTest();check(window.SaveSettingsForTest(),"A synchronous save supersedes a pending background history task");failure.SetException(new IOException("Obsolete fixture failure"));Application.Current.Dispatcher.Invoke(DispatcherPriority.ApplicationIdle,new Action(()=>{}));check(!window.HistoryDirtyForTest,"A late obsolete writer failure cannot mark a newer successful save dirty");
    failure=new TaskCompletionSource<bool>();window.WriteHistoryAsync=(snapshot,path)=>failure.Task;window.LogHistoryForTest("latest-error");window.FlushHistoryForTest();failure.SetException(new IOException("Current fixture failure"));PumpUntil(()=>window.HistoryDirtyForTest);check(window.HistoryDirtyForTest,"The latest background write failure remains pending for recovery");
    window.Close();check(Storage.Read(file).History.Any(h=>h.Name=="latest-error"),"Closing after a failed background write persists the latest history synchronously");
    state=StateWith("pending-close");file=Path.Combine(root,"close.json");window=new MainWindow(state,file){Owner=owner};window.Show();Storage.Snapshot waiting=null;var finish=new TaskCompletionSource<bool>();window.WriteHistoryAsync=(snapshot,path)=>{waiting=snapshot;return finish.Task;};window.LogHistoryForTest("final-close");window.FlushHistoryForTest();window.Close();Storage.Write(waiting,file);finish.SetResult(true);check(Storage.Read(file).History[0].Name=="final-close","Closing while a write is pending saves a newer snapshot that a late writer cannot overwrite");
   }finally{if(window.IsVisible)window.Close();Clean(root);}
  }
  static void HookPaths(Action<bool,string> check){
   using(var engine=new KeyboardEngine()){
    int queries=0,fires=0;string app=System.Reflection.Assembly.GetExecutingAssembly().Location;engine.QueryForegroundPath=w=>{queries++;return app;};var binding=new Binding{Key=119,AppPath=app,Kind="Send key",SendKey=83,SendMods=2};var bindings=new List<Binding>{binding};engine.Bindings=()=>bindings;engine.Fire=(b,w)=>fires++;
    engine.Handle(new Native.Keyboard{vk=118});engine.Handle(new Native.Keyboard{vk=118,flags=128});engine.Handle(new Native.Keyboard{vk=162});engine.Handle(new Native.Keyboard{vk=119});engine.Handle(new Native.Keyboard{vk=119,flags=128});engine.Handle(new Native.Keyboard{vk=162,flags=128});engine.FlushForTest();check(queries==0&&fires==0,"Unbound and mismatched-modifier keys do not query the foreground process");
    engine.Handle(new Native.Keyboard{vk=119});engine.Handle(new Native.Keyboard{vk=119,flags=128});engine.FlushForTest();check(queries==1&&fires==1,"A bound app-scoped key resolves its foreground path and dispatches once");
    engine.ExpireForegroundCacheForTest();binding.Enabled=false;engine.Handle(new Native.Keyboard{vk=119});engine.Handle(new Native.Keyboard{vk=119,flags=128});engine.FlushForTest();engine.MouseForTest(0x20B,new Native.MouseEvent{Data=1u<<16});engine.MouseForTest(0x20C,new Native.MouseEvent{Data=1u<<16});engine.MouseForTest(0x20A,new Native.MouseEvent{Data=120u<<16});check(queries==1,"Disabled shortcuts and unbound pointer inputs avoid foreground process lookup");
    binding.Enabled=true;binding.Key=5;engine.ExpireForegroundCacheForTest();bool blocked=engine.MouseForTest(0x20B,new Native.MouseEvent{Data=1u<<16});engine.MouseForTest(0x20C,new Native.MouseEvent{Data=1u<<16});engine.FlushForTest();check(!blocked&&fires==1&&queries==2,"The app-own-window pointer exclusion is preserved for candidate bindings");engine.AllowOwnPointerForTest=true;engine.MouseForTest(0x20B,new Native.MouseEvent{Data=1u<<16});engine.MouseForTest(0x20C,new Native.MouseEvent{Data=1u<<16});engine.FlushForTest();check(fires==2&&queries==2,"Bound pointer input uses the cached path and retains controlled opt-in behavior");
    engine.AllowOwnPointerForTest=false;bindings.Clear();bindings.Add(new Binding{Key=53,PrefixKey=46,AppPath=app});int replayed=0;engine.ReplayRaw=keys=>replayed++;engine.ReplayKey=(mods,key)=>replayed++;engine.ExpireForegroundCacheForTest();engine.Handle(new Native.Keyboard{vk=46});engine.ExpireForegroundCacheForTest();blocked=engine.MouseForTest(0x20B,new Native.MouseEvent{Data=1u<<16});engine.MouseForTest(0x20C,new Native.MouseEvent{Data=1u<<16});check(!blocked&&replayed==0&&queries==4,"Unbound pointer input during a pending prefix preserves the own-window exclusion without replaying a mouse key as keyboard input");engine.Handle(new Native.Keyboard{vk=46,flags=128});engine.FlushForTest();check(replayed==1&&fires==2,"The unused prefix retains its normal replay behavior after an excluded own-window click");
   }
  }
 }
